// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract Reverter {
    fallback() external payable { revert(); }
}

contract InvMutTest is Test {
    Reentrance c;
    Reverter reverter;

    function setUp() public {
        c = new Reentrance();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 amount, uint256 otherAmount, address actor, address other) public {
        vm.assume(otherAmount <= VALUE_CAP);
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && other != address(0));
        vm.assume(actor != other);
        vm.assume(actor != address(reverter));
        vm.assume(other != address(reverter));

        amount = bound(amount, 1, type(uint128).max);
        otherAmount = bound(otherAmount, 1, type(uint96).max);

        vm.deal(other, otherAmount);
        vm.prank(other);
        c.addToBalance{value: otherAmount}();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 beforeActorBalance = c.getBalance(actor);
        uint256 beforeOtherBalance = c.getBalance(other);
        uint256 beforeContractBalance = address(c).balance;

        vm.prank(actor);
        bool ok; try c.withdrawBalance() { ok = true; } catch { ok = false; }

        assertTrue(
            !ok ||
            (c.getBalance(actor) == 0 &&
             c.getBalance(other) == beforeOtherBalance &&
             address(c).balance >= beforeOtherBalance &&
             beforeActorBalance + beforeOtherBalance == beforeContractBalance)
        );
    }
}
